"""Write docs/bg-probe.md from docs/bg-probe.yaml: uv run python scripts/bg_probe.py"""
import subprocess
from pathlib import Path

import yaml

from mtglang.evalen import evaluate
from mtglang.ortho.glossary import load_overrides
from mtglang.ortho.ivanchev import to_ivanchev

ROOT = Path(".")
data = yaml.safe_load(open("docs/bg-probe.yaml", encoding="utf-8"))
results = {r.ref: r for r in evaluate(ROOT)}
words = load_overrides(ROOT)[0]
out = ["# Bulgarian probe of the plan IR", "",
       "Generated by `scripts/bg_probe.py` from `docs/bg-probe.yaml`. Each Bulgarian rendering was written from",
       "the clause plan (`scripts/plan_dump.py`) and the glossary's `bg` labels alone, to check that the",
       "language-neutral planner carries everything a Bulgarian realizer needs (English renderer plan, Task 11).",
       "", "**Result:** three facts were missing and are now in the plan — `ClausePlan.aspect` (state *има* /",
       "change *придобива*), `ClausePlan.tense = past` for completed events in conditions (*са загинали*), and",
       "`parts.once` for triggers on one-time events (*когато встъпи* / *щом напада*). Everything else the",
       "Bulgarian needed is either in the plan or a property of a word (gender, numeral and participle forms) —",
       "data for a future `lex.bg`, not for the planner.", ""]
for k, e in enumerate(data, 1):
    r = results[e["ref"]]
    dump = subprocess.run(["uv", "run", "python", "scripts/plan_dump.py", e["ref"]], capture_output=True,
                          text=True, check=True).stdout.split("\n", 1)[1].rstrip()
    out += [f"## {k}. `{e['ref']}`", "", f"- notation: `{r.notation}`", f"- Oracle: {r.oracle}",
            f"- rendered English: {r.rendered}" + ("" if r.match else "  *(differs from Oracle)*"),
            f"- **Bulgarian:** {e['bg']}", f"- **Ivanchev:** {to_ivanchev(e['bg'], words)}", "", "Needed:", ""]
    out += [f"- {n}" for n in e["needs"]]
    out += ["", "<details><summary>plan</summary>", "", "```", dump, "```", "", "</details>", ""]
Path("docs/bg-probe.md").write_text("\n".join(out), encoding="utf-8")
print("wrote docs/bg-probe.md")
